const { summary, description, location, startDateTime, endDateTime, timeZone, attendees, sendUpdates } = $.input;
if (!summary || !startDateTime || !endDateTime) throw new Error('summary, startDateTime, and endDateTime are required');

const isAllDay = /^\d{4}-\d{2}-\d{2}$/.test(startDateTime);
const event = { summary };

if (description) event.description = description;
if (location) event.location = location;

if (isAllDay) {
  event.start = { date: startDateTime };
  event.end = { date: endDateTime };
} else {
  event.start = { dateTime: startDateTime };
  event.end = { dateTime: endDateTime };
  if (timeZone) {
    event.start.timeZone = timeZone;
    event.end.timeZone = timeZone;
  }
}

if (attendees) {
  event.attendees = attendees.split(',').map(e => ({ email: e.trim() })).filter(a => a.email);
}

const queryParams = {};
if (sendUpdates) queryParams.sendUpdates = sendUpdates;

return { event, queryParams };

const resp = $.steps.createEvent.response || {};
return {
  eventId: resp.id || '',
  htmlLink: resp.htmlLink || '',
  summary: resp.summary || $.input.summary,
  start: resp.start || {},
  end: resp.end || {},
  status: resp.status || '',
  created: !!resp.id,
  result: resp.id ? `Created event "${resp.summary || $.input.summary}"` : 'Failed to create event'
};
